package com.example.demo.weakvocabulary.service.impl;
import com.example.demo.common.exception.ResourceNotFoundException; import com.example.demo.flashcard.entity.Flashcard; import com.example.demo.flashcard.repository.FlashcardRepository; import com.example.demo.user.entity.User; import com.example.demo.user.repository.UserRepository; import com.example.demo.weakvocabulary.dto.WeakDtos.*; import com.example.demo.weakvocabulary.entity.UserWeakVocabulary; import com.example.demo.weakvocabulary.repository.UserWeakVocabularyRepository; import com.example.demo.weakvocabulary.service.WeakVocabularyService; import jakarta.persistence.criteria.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class WeakVocabularyServiceImpl implements WeakVocabularyService { private final UserWeakVocabularyRepository repo; private final UserRepository users; private final FlashcardRepository flashcards;
 public WeakResponse addManual(Long uid,Long fid){ UserWeakVocabulary w=repo.findByUserIdAndFlashcardId(uid,fid).orElseGet(()->UserWeakVocabulary.builder().user(user(uid)).flashcard(card(fid)).build()); w.setManualMarked(true); w.setWeakDeleted(false); w.setWeakDeletedAt(null); return map(repo.save(w)); }
 public void recordStudyDifficulty(Long uid,Long fid,int q){ if(q>3)return; UserWeakVocabulary w=repo.findByUserIdAndFlashcardId(uid,fid).orElseGet(()->UserWeakVocabulary.builder().user(user(uid)).flashcard(card(fid)).build()); if(w.isWeakDeleted()) return; w.setAutoDetected(true);w.setLastStudyQuality(q);repo.save(w); }
 public PageResponse list(Long uid,String keyword,Long deck,String source,Integer min,Integer max,Double amin,Double amax,String sort,int page,int size){ Specification<UserWeakVocabulary> s=(r,q,cb)->cb.and(cb.equal(r.get("user").get("id"),uid),cb.isFalse(r.get("weakDeleted"))); if(keyword!=null&&!keyword.isBlank()) {String k="%"+keyword.toLowerCase()+"%";s=s.and((r,q,cb)->cb.or(cb.like(cb.lower(r.get("flashcard").get("vocabulary")),k),cb.like(cb.lower(r.get("flashcard").get("meaning")),k)));} if(deck!=null)s=s.and((r,q,cb)->cb.equal(r.get("flashcard").get("deck").get("id"),deck)); if(source!=null&&!source.equals("ALL")) s=s.and((r,q,cb)-> switch(source){case "AUTO"->cb.isTrue(r.get("autoDetected"));case "MANUAL"->cb.isTrue(r.get("manualMarked"));case "BOTH"->cb.and(cb.isTrue(r.get("autoDetected")),cb.isTrue(r.get("manualMarked")));default->cb.conjunction();}); if(min!=null)s=s.and((r,q,cb)->cb.ge(r.get("masteryScore"),min));if(max!=null)s=s.and((r,q,cb)->cb.le(r.get("masteryScore"),max)); if(amin!=null)s=s.and((r,q,cb)->cb.ge(cb.quot(r.get("correctCount").as(Double.class),cb.nullif(r.get("totalAttempts").as(Double.class),0d)),amin/100));if(amax!=null)s=s.and((r,q,cb)->cb.le(cb.quot(r.get("correctCount").as(Double.class),cb.nullif(r.get("totalAttempts").as(Double.class),0d)),amax/100)); Sort order=switch(sort==null?"WEAKEST_FIRST":sort){case "MASTERY_DESC"->Sort.by("masteryScore").descending();case "UPDATED_DESC"->Sort.by("updatedAt").descending();case "WORD_ASC"->Sort.by("flashcard.vocabulary").ascending();case "WORD_DESC"->Sort.by("flashcard.vocabulary").descending();default->Sort.by("masteryScore").ascending();}; Page<UserWeakVocabulary> result=repo.findAll(s,PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),order)); return PageResponse.builder().items(result.map(this::map).getContent()).page(result.getNumber()).size(result.getSize()).totalElements(result.getTotalElements()).totalPages(result.getTotalPages()).first(result.isFirst()).last(result.isLast()).build(); }
 public WeakResponse patch(Long uid,Long id,PatchRequest r){UserWeakVocabulary w=owned(uid,id);if(r.getWeakNote()!=null)w.setWeakNote(r.getWeakNote());if(r.getManualMarked()!=null)w.setManualMarked(r.getManualMarked());return map(repo.save(w));} public void softDelete(Long uid,Long id){UserWeakVocabulary w=owned(uid,id);w.setWeakDeleted(true);w.setWeakDeletedAt(LocalDateTime.now());repo.save(w);} private UserWeakVocabulary owned(Long u,Long id){return repo.findById(id).filter(w->w.getUser().getId().equals(u)&&!w.isWeakDeleted()).orElseThrow(()->new ResourceNotFoundException("Weak vocabulary not found"));} private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));} private Flashcard card(Long id){return flashcards.findById(id).orElseThrow(()->new ResourceNotFoundException("Flashcard not found"));}
 private WeakResponse map(UserWeakVocabulary w){Flashcard f=w.getFlashcard();double a=w.getTotalAttempts()==0?0:Math.round(w.getCorrectCount()*10000d/w.getTotalAttempts())/100d;String reason=w.isManualMarked()?"MANUAL_MARK":w.getConsecutiveWrong()>=2?"CONSECUTIVE_WRONG":w.getLastStudyQuality()!=null&&w.getLastStudyQuality()<=1?"STUDY_FORGOT":w.getLastStudyQuality()!=null&&w.getLastStudyQuality()<=3?"STUDY_HARD":w.getTotalAttempts()>=3&&a<60?"LOW_PRACTICE_ACCURACY":"STUDY_HARD";return WeakResponse.builder().weakVocabularyId(w.getId()).flashcardId(f.getId()).deckId(f.getDeck()==null?null:f.getDeck().getId()).deckName(f.getDeck()==null?null:f.getDeck().getName()).vocabulary(f.getVocabulary()).meaning(f.getMeaning()).phonetic(f.getPhonetic()).exampleSentence(f.getExampleSentence()).manualMarked(w.isManualMarked()).autoDetected(w.isAutoDetected()).masteryScore(w.getMasteryScore()).totalAttempts(w.getTotalAttempts()).correctCount(w.getCorrectCount()).wrongCount(w.getWrongCount()).consecutiveWrong(w.getConsecutiveWrong()).accuracy(a).weakReason(reason).weakNote(w.getWeakNote()).lastStudyQuality(w.getLastStudyQuality()).lastPracticedAt(w.getLastPracticedAt()).createdAt(w.getCreatedAt()).updatedAt(w.getUpdatedAt()).build();}}
